\chapter{Die Schmiede: Feuer, Eisen und die Farben der Verantwortung}

\begin{warnbox}
Schmiedefeuer erzeugen Kohlenmonoxid. In geschlossenen Räumen ohne durchgehenden Zug nach außen ist CO-Vergiftung möglich -- die Warnzeichen sind Kopfschmerz, Schwindel, Übelkeit. Die Schmiede-Feuerstelle niemals in bewohnten Räumen betreiben. Abstand zu brennbarem Material mindestens 2 m, Untergrund aus Mineralischem (Sand, Stein, Beton). Wer Farbe am Eisen über Gelbglut hinaus treibt, zerstört das Gefüge; die Gefahr ist unsichtbar: Das Stück kann später unter Last brechen, ohne Vorankündigung.
\end{warnbox}

\begin{konzept}{2.1}{Feuerstelle und Gebläse}
\textbf{Definition:} Eine Schmiede-Feuerstelle ist ein offener Herd mit feuerfestem Bett, Luftzufuhr von unten und Aschenfall, gebaut um ein Arbeitstemperatur-Fenster von etwa 1100 bis 1300 °C im Glutkern.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Ort: Offener Himmel oder offene Halle, Zug nach außen, 2 m Freiraum ringsum; Untergrund mineralisch.
  \item Luft: Gebläse oder Blasebalg mit regelbarer Förderung; Rohr aus Stahl, nicht aus Kunststoff.
  \item Brennstoff: Holzkohle (Lager-/Hartholz, ausgebrannt, Fauststück-groß) oder Kohle; ungeeichte Mengen vorab wiegen.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Temperaturkonstanz: Hält der Kern 15 Minuten Arbeitstemperatur bei ruhiger Luft?
  \item Brennstoffverbrauch: Verhältnis verbrannter Brennstoff zu bearbeiteten Stücken notieren.
  \item Handhabung: Lässt sich die Luft in drei Stufen regeln, ohne die Hand vom Werkstück zu nehmen?
\end{enumerate}

\textbf{Ehrliche Grenzen:} Ohne Gebläse sind nur temperaturempfindliche Arbeiten nahe dem Schweißfenster möglich, aber langsam. Gasgebläse aus Abfall (Föhn-Motor, 12-V-Lüfter) funktionieren kurzzeitig -- Lebensdauer und Spannungsversorgung örtlich prüfen.

\subsection{Tabelle: Feuerstelle Stadt/Land (Tab. 2.1)}
\begin{tabular}{p{3.6cm}p{4.4cm}p{4.4cm}}
\toprule
Merkmal & Stadt & Land \\
\midrule
Standort & Innenhof, Dachterrasse mit Abzug, Parkplatz aus Beton & Waldlichtung mit Sandbett, abseits der Scheune \\
Brennstoff & Holzkohle aus Gartengrill, Restausholz (unlackiert) & Eigenköhlung (Konzept 7.4), Buche, Esche \\
Gebläse & Handblasebalg, 12-V-Lüfter mit Akku & Blasebalg, Tretgebläse,acquﬁr Nie Sorry -- Lederbalg \\
Aschenfall & Blechdose 2 l mit Deckel & gemauerte Grube 40 cm tief \\
Notwasser & Eimer 10 l, Deckel, am Feuerplatz & Eimer oder Regentonnen-Eimer am Feuerplatz \\
\bottomrule
\end{tabular}

\subsection{Schritte: Feuerstelle bauen (Tab. 2.2 als Prüfmaß)}
\begin{enumerate}
  \item Flächen 1,5 m × 1,5 m von Brennbarem freimachen; Untergrund prüfen (Mineralisch? Wenn nein: Sand 5 cm aufbringen).
  \item Feuerbett ausrunden: Mulde 30 cm Durchmesser, 8 cm tief, in Sand oder feuerfestem Stein.
  \item Luftrohr (Stahl, 20 bis 25 mm Innendurchmesser) von unten mittig durch die Mulde führen; Rohr-Öffnung mit Lochblech gegen Verschlackung sichern.
  \item Aschenfall unter dem Rohr anbringen; Rohr um 5° zur Falle geneigt.
  \item Notwassereimer 10 l füllen, ablegen; Löschstange bereitlegen.
  \item Holzkohle 3 cm hoch einfüllen, Anfeuerholz 5 Handvoll obendrauf, anzünden.
  \item Gebläse anstellen; bei ruhiger Flamme Luft erhöhen, bis der Kern gelb leuchtet.
  \item Kohle nachlegen, sobald Rand aschig wird -- stets am Rand, nie auf den Arbeitskern.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Orange glüht, gelb schmiedet, gelbweiß brennt das Stück.\\
Luft von unten macht Hitze; Luft von der Seite macht Funken.\\
Funkenflug auf entzündbarem Boden: Feuer sofort räumen.
\end{baustein}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-2-1}
\caption{Abb. 2.1 -- Aufbau der Schmiede-Feuerstelle: Mulde, Luftrohr, Aschenfall, Sicherheitszone}
\end{figure}
\end{konzept}

\begin{konzept}{2.2}{Grundhiebe: Strecken, Stauchen, Absetzen}
\textbf{Definition:} Grundhiebe sind die vier Bewegungen, aus denen jede Schmiedearbeit zusammengesetzt ist: Strecken (Querschnitt verringern, Länge wächst), Stauchen (Querschnitt wächst), Absetzen (scharfe Kante/Fase), Biegen (Richtung ändern ohne Materialverlust).

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Material: Ist der Stahl schmiedbar? Prüfung: Im Kern gelb glühen und hämmern -- federt er hart zurück, ist es Werkzeugstahl (härter, bruchempfindlicher).
  \item Amboss: Sitzt die Fläche auf 60 bis 70 cm Stumpf? Größerer Amboss besser als Zwerg mit loses Stumpf.
  \item Hammer: 0,7 bis 1,2 kg Kopfgewicht für Handarbeit; Stiel rissfrei.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Form: Gewichtsvergleich des Stücks vor/nach -- sollte gleich sein, Stauchen verliert nie Material, aber Überhitzung verbrennt Stahl sichtbar (Funkenschweifen).
  \item Oberfläche: Hammermarken gleichmäßig, Tiefe geringer als 1 mm -- prüfbar mit Fingernagel.
  \item Maßhaltigkeit: Abweichung vom Zielmaß unter ±2 mm (Faustwert).
\end{enumerate}

\textbf{Ehrliche Grenzen:} Ohne Öl-Härtemaschine, nur mit Amboss und Hammer, lassen sich Zusammenhänge bis etwa 25 mm Querschnitt zuverlässig bearbeiten. darüber wird Handkraft unökonomisch -- nutzen: Baustelle organisieren, zwei Hämmer, zwei Hände.

\subsection{Tabelle: Grundhiebe (Tab. 2.3)}
\begin{tabular}{p{2.8cm}p{4cm}p{4.6cm}}
\toprule
Hieb & Bewegung & Fehler \\
\midrule
Strecken & Auf halber Ambossbreite schlagen, Stück zwischen Schlägen 90° drehen & Dünner Bereich kalt gehämmert = Risse \\
Stauchen & Ende auf dem Amboss schlagen, Stück aufrecht halten & Stück knickt; gerade halten, langsam arbeiten \\
Absetzen & Am Ambosshorn scharfe Fase ziehen, Wasser ansetzen & Fase zu scharf = späterer Bruch dort \\
Biegen & Am Horn legen, drücken, nicht schlagen & Kaltes Biegen über 5 mm Dicke = Risse \\
\bottomrule
\end{tabular}

\subsection{Schritte: erstes Strecken (Übung)}
\begin{enumerate}
  \item Rundstab 12 mm, 100 mm lang, im Kern gelb glühen.
  \item Auf halber Ambossfläche ansetzen; 4 Schläge, dann 90° drehen.
  \item Nach 16 Schlägen Maße prüfen: Soll 100 × 8 × 8 mm nach zwei Gluten.
  \item Fehlerbild nach Tab. 2.3 korrigieren, Stück erst abkühlen lassen, dann messen.
  \item Übung 10× wiederholen; erst danach am echten Werkstück (Konzept 2.3, 5.4).
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Schlage auf heißem Stück, niemals auf kaltem -- kalter Stahl bricht.\\
Der Hammer trifft die Stelle, die das Auge ansieht; wegsehen = Fehlschlag.\\
Nach jedem Zug Wasser prüfen: Eimer voll, Deckel drauf.
\end{baustein}
\end{konzept}

\begin{konzept}{2.3}{Härten und Anlassen}
\textbf{Definition:} Härten ist das Abschrecken von kohlenstoffhaltigem Stahl aus cherryroter Glut (etwa 750 bis 800 °C, Farbvergleich mit Tab. 2.4) in Wasser oder Öl; Anlassen ist das kontrollierte Wiedererwärmen auf 200 bis 300 °C, um Sprödigkeit zu senken -- die Farben der Verantwortung zeigen die Temperatur an der Oberfläche an.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Stahlsorte: Magnettest beim Glühen -- verliert der Stahl bei Kirschrot seine magnetische Wirkung, enthält er genug Kohlenstoff zum Härten (Faustwert, keine Garantie).
  \item Abschreckmittel: Wasser (hart, Rissgefahr bei dünnem Querschnitt) oder Öl (mäßiger, ruhiger); beide mindestens 10 l, Temperatur unter 40 °C halten.
  \item Spannungsarme Form: Scharfe Kanten vor dem Härten brechen mit 1-mm-Fase breit, R Radius mindestens 2 mm.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Härteprüfung (Feiltest): Neue Feile gleitet, ohne zu greifen = ausreichend hart; greift sie, ist das Stück weich geblieben.
  \item Anlassfarbe: Gleichmäßig strohgelb bis braun über der Fläche, nicht fleckig.
  \item Bruchtest am Probestück (nicht am Werkstück): Probestück gleicher Stahl mithärten und auf Biegung prüfen.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Ohne bekannte Stahlsorte ist die Härte ein Glücksspiel. Die Farben zeigen Oberflächentemperatur an, nicht den Kern. Werkzeuge, die Leben sichern (Seil-Ösen, Bremshebel), nur aus bekanntem Stahl oder mit Probestück-Reihe (5 Stück, je eines brechen) herstellen.

\subsection{Tabelle: Anlassfarben (Tab. 2.4)}
\begin{tabular}{p{3.6cm}p{3.8cm}p{4.6cm}}
\toprule
Farbe & Temperaturbereich & Eignung \\
\midrule
Blasses Silber & unter 200 °C & zu spröde, nacharbeiten \\
Strohgelb & etwa 220 bis 240 °C & Meißel, Stichel \\
Braun & etwa 240 bis 260 °C & Äxte, Hackmesser \\
Violett & etwa 270 bis 290 °C & Federn, Schnäpper \\
Blau & etwa 290 bis 320 °C & wenig Härte, zäher Bauteil-Stahl \\
Grau/blau-grau & über 320 °C & weich, für Federn ungeeignet \\
\bottomrule
\end{tabular}

\subsection{Schritte: Härten eines Meißels}
\begin{enumerate}
  \item Stahl bestimmen (Magnetttest Konzept 2.3); Probestücke 5 Stück mitschneiden.
  \item Arbeitsstück auf Kirschrot (~780 °C) im Kern glühen; Farbe gegen Tab. 2.4 prüfen (unten: Farbvergleich beim Härten).
  \item Spitze 20 mm ins Wasser tauchen, senkrecht, ruhig bewegen; 5 Sekunden.
  \item Ganzes Stück herausnehmen, Oberfläche blank reiben, Anlassen beobachten: Farbe wandert zur Spitze.
  \item Bei strohgelb an der Spitze: Ganzes Stück ins Wasser.
  \item Feiltest (Bewertung 1) durchführen; Probestück brechen und Bruchfläche ansehen (feinkörnig = gut).
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Kirschrot härten, strohgelb anlassen.\\
Wasser ist schnell, Öl ist barmherzig.\\
Ohne Probestück ist Härten ein Würfelspiel.
\end{baustein}
\end{konzept}

\begin{konzept}{2.4}{Schmieden ohne Schmiede: Reiseausrüstung}
\textbf{Definition:} Die Reise-Schmiede ist die auf 8 kg begrenzte Ausrüstung, mit der kleine Arbeiten (Nägel, Haken, Angelhaken, Beschläge) am Feldherd möglich sind -- nicht aber Härtungen oder Zusammenhänge.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Tragegewicht: Gesamtgewicht unter 8 kg inkl. Brennstoff für 3 Stunden.
  \item Unterlage: Findling, Eisenbahnschiene-Stück oder Baumstumpf mit Stahlplatte; Mindestgewicht 5 kg als Stumpf.
  \item Feuer: Trench-Feuer (Graben 30 × 20 × 15 cm) mit Luftkanal aus Lehm oder Blech.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Stückzahl: 3 Stück pro Stunde sind gutes Ergebnis (Faustwert).
  \item Werkzeug-Zustand: Zangen, Hammer, Amboss unverändert nach Tab. 6.2 geprüft.
  \item Sicherheit: Notwasser, Brandschneise 2 m, Asche entsorgt.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Die Reise-Schmiede härtet nicht zuverlässig (kein Ölbad, keine Farbkontrolle bei Wind). Nutze sie für Formarbeit, nicht für Werkzeuge, die halten müssen.

\subsection{Tabelle: Reise-Schmiede Packliste (Tab. 2.5)}
\begin{tabular}{p{4.4cm}p{2.6cm}p{4.6cm}}
\toprule
Gegenstand & Gewicht & Ersatz \\
\midrule
Hammer 0,8 kg & 0,8 kg & Flusskiesel mit Fläche, nur für grobe Form \\
Zange 30 cm & 0,5 kg & Zwei Hartholz-Klemmen \\
Rohrzange (Durchmesser-Sicherung) & 0,5 kg & Drahtschlinge am Stiel \\
Amboss-Stumpf (Stahlplatte 10 cm) & 3,0 kg & Findling oder Schienenstück \\
Blasebalg klein & 0,7 kg & Rohr blasen mit Lungenkraft (kurz, mühsam) \\
Holzkohle, 3 Stunden & 2,0 kg & Buchen-Restholz, trocken \\
\bottomrule
\end{tabular}

\subsection{Schritte: Trench-Feuer aufbauen}
\begin{enumerate}
  \item Graben 30 cm lang, 20 cm breit, 15 cm tief, Ausrichtung in Windrichtung.
  \item Luftkanal (Durchmesser 4 cm) von der Längsseite in die Grubenmitte graben.
  \item Lehm aus der Grube als Rand aufschichten; Blechdeckel über dem Kanal gegen Verschmutzung.
  \item Kohle füllen, Randholz anzünden, Luft durch Kanal blasen.
  \item Nach 10 Minuten Kern prüfen: gelber Kern = Arbeitsbereitschaft (Konzept 2.1 Merksatz).
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Kleine Schmiede für kleine Teile; Haken, Nägel, Ösen -- nichts was Leben hält.\\
Findling ersetzt Amboss, nicht aber Formarbeit am Horn.
\end{baustein}
\end{konzept}

\section{Kapitel-Checkliste: Die Schmiede}
\begin{checkliste}
  \item ☐ Feuerplatz steht offen, 2 m Freiraum, mineralischer Untergrund.
  \item ☐ Notwasser 10 l mit Deckel am Platz, Löschstange bereit.
  \item ☐ Gebläse in drei Stufen regelbar, Rohr aus Stahl.
  \item ☐ Farbtafel Tab. 2.4 liegt beim Amboss.
  \item ☐ Nie unter 15 °C Stücktemperatur gehämmert (Rissgefahr).
  \item ☐ Jede Härtung mit 5 Probestücken begleitet.
  \item ☐ Anlassfarbe über der Fläche gleichmäßig, nicht fleckig.
  \item ☐ Reise-Schmiede nur für Formarbeit, nicht für Sicherheitsteile.
  \item ☐ Asche kalt (unter 50 °C, Faustwert: Hand 5 cm darüber 10 s aushalten) entsorgt.
\end{checkliste}
