\chapter{Das Holz: lesen, fällen, zerlegen}

\begin{warnbox}
Beim Fällen mit Axt oder Säge kann der Stamm zur Fallkerbseite zurückschlagen („Rückschlag", Bar-Chair-Effekt), wenn der Fällschnitt klemmt. Klemmschnitt sofort lösen, niemals am Stamm herumdrehen. Fluchtwege: Zwei Wege im 45°-Winkel zur Rückrichtung freimachen, mindesten 4 m frei von Gestrüpp. Kopf oben halten, den fallenden Kronenbereich nie beobachten -- Kronen werfen Äste („Widow-Maker"). Wer zum ersten Mal fällt: nur Bäume unter 20 cm Brusthöhen-Durchmesser, kein hängender Stamm, kein windiger Tag.
\end{warnbox}

\begin{konzept}{3.1}{Holz lesen}
\textbf{Definition:} Holz lesen heißt, an Rinde, Wuchs, Klang und Geruch zu erkennen, ob ein Stamm für tragende, feuertragende oder nur für Brennholz-Zwecke taugt -- und wo es bricht.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Klang: Klopfprobe -- heller Ton = fest, dumpfer Ton = Fäulnis oder Riss (Faustwert).
  \item Wuchs: Spirale in der Rinde = Drillwuchs, bricht unregelmäßig; Astlöcher bis Mark = mindertragend.
  \item Feuchte: Frisch gefällt 35 bis 55 \% Wassergehalt (Faustwert), lagergetrocknet unter 20 \%; ohne Messgerät: Bohrspanwiegung (Vorlage A.5).
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Lastfestigkeit: Probestab 20 × 2 × 2 cm aus Mitte, 30 s auf zwei Auflagern belasten mit 10 kg; Durchbiegung unter 2 mm.
  \item Splitterfestigkeit: Sägeprobe am Ende -- Splitter lang = zähe, Splitter kurz = spröde.
  \item Geruch: Säure-Geruch (essigartig) = beginnender Pilzbefall; Erde-Geruch = Braunfäule.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Ohne Messgerät bleibt die Feuchte-Schätzung ungenau. Für tragende Strukturen gilt die Faustregel: Frischholz (über 20 \% Feuchte) nicht unter Last verbauen, ohne Tragreserve von 2×.

\subsection{Tabelle: Holz-Eignung nach Einsatzzweck (Tab. 3.1)}
\begin{tabular}{p{2.8cm}p{3.6cm}p{3.8cm}p{2.6cm}}
\toprule
Holz & Tragend & Feuer (Brennwerte) & Wasser/Erde \\
\midrule
Eiche & gut, hart & gut, lange Glut & sehr dauerhaft \\
Buche & gut, hart & beste Holzkohle & fault in Erde \\
Esche & sehr gut, zäh & gut & mäßig \\
Fichte & mäßig, leicht & schnell, Funken & fault schnell \\
Kiefer & mäßig, harzig & schnell, rußt & Kern dauerhaft \\
Erle & schlecht & mäßig & sehr gut im Wasser \\
\bottomrule
\end{tabular}

\subsection{Schritte: Baum in 3 Minuten einschätzen}
\begin{enumerate}
  \item Um den Stamm gehen; Rinde auf Spiralwuchs prüfen.
  \item Klopfprobe an drei Höhen: Fuß, Mitte, Brusthöhe.
  \item Wurzelansatz ansehen: Pilz-Früchte, Auskülungen, Rindeneinrisse.
  \item Krone ansehen: Totholz, einseitiger Astwuchs = Fallrichtung gegen Astseite.
  \item Einsatzzweck festlegen (Tab. 3.1) und auf dem Stamm markieren: T = tragend, F = Feuer, W = Wasser/Erd-Bau.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Dumper Klang: Der Baum lügt nicht, er fault.\\
Frisch verbaut, feucht gebaut -- im nächsten Jahr nachgesackt.\\
Eiche hält in Wasser, Buche fault in Erde.
\end{baustein}
\end{konzept}

\begin{konzept}{3.2}{Fällen mit Axt und Handsäge}
\textbf{Definition:} Fällen heißt, einen stehenden Baum mit Fallkerb und Fellschnitt (Fällschnitt) kontrolliert in eine gewählte Richtung zu bringen -- bei Handarbeit in drei Schnitten: Fallkerb (V), Stich auf Höhe, Trennschnitt von hinten.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Fallrichtung: Hang, Ast-Last, Wind, Nachbarschaft -- Zielrichtung 1,5× Baumhöhe freihalten (Faustwert).
  \item Werkzeug: Säge scharf (Konzept 4.2), Axt geschlossen, Helm oder Kapuze, festes Schuhwerk.
  \item Mensch: Nie alleine fällen; die zweite Person steht 10 m seitlich mit Sichtkontakt.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Scharnier: Ist der Stand-Spalt (Bruchleiste) 10 \% des Durchmessers breit geblieben?
  \item Fallort: Baum liegt in der geplanten Richtung, keine Nebenschäden.
  \item Zeit: Bruttozeit unter 3× der Schätzung für nächste Planung notieren.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Hängende Stämme, Druck am Stamm (Wind, Nachbarschaft), Durchmesser über 30 cm: ohne Spreize oder Seilwinde nicht fällen. Zurücklehnen und den Baum stehen lassen ist eine bewertete Entscheidung nach Konzept 1.1, kein Versagen.

\subsection{Tabelle: Fäll-Entscheidung Stadt/Land (Tab. 3.2)}
\begin{tabular}{p{3.6cm}p{4.4cm}p{4.4cm}}
\toprule
Kriterium & Stadt & Land \\
\midrule
Durchmesser maximal & 20 cm Brusthöhe (Handarbeit) & 30 cm mit Zweitschnitt und Spreizhilfe \\
Fallraum & 1,5× Höhe + 2 m zu Bauwerk & 1,5× Höhe, Nachbarn fragen \\
Genehmigung & Gemeinschaftsentscheid, Besitz klären & Hofregel, Grenzabstand 3 m (Faustwert) \\
Wind & unter Stärke 3 (Blätter bewegen sich) & unter Stärke 4 (Zweige bewegen sich) \\
Zweite Person & Pflicht & Pflicht \\
\bottomrule
\end{tabular}

\subsection{Schritte: Fällschnitt}
\begin{enumerate}
  \item Fallrichtung bestimmen (Tab. 3.2); Fluchtwege zwei, 45° rückwärts, 4 m frei.
  \item Rinde im Brusthöhen-Bereich freilegen, Durchmesser messen.
  \item Fallkerb: Zwei Axt-Schnitte oder Sägeschnitte in V-Form, Tiefe ein Drittel des Durchmessers, öffnet in Fallrichtung.
  \item Gegenprobe: Kerb zeigt auf Ziel, Zielrichtung 5 m weiter frei.
  \item Fellschnitt von hinten: Etwa 5 cm über Kerbsohle, horizontal, 3 bis 5 cm vor dem Kerb stehen lassen (Bruchleiste).
  \item Beim Öffnen des Scharniers zurücktreten, in Fluchtweg ein; Beobachten des Stammfußes, nicht der Krone.
  \item Nach dem Fall 2 Minuten warten: Nachfallende Äste, Spannungen im Stamm.
  \item Scharnier-Breite messen (Bewertung 1), Zeit notieren (Vorlage A.5).
\end{enumerate}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-3-1}
\caption{Abb. 3.1 -- Fällschnitt: Fallkerb, Fellschnitt, Bruchleiste, Fluchtwege}
\end{figure}

\begin{baustein}
\textbf{Merksätze.}\\
Der Fallkerb zeigt, wohin der Baum will.\\
Bruchleiste bleibt: ein Zehntel, nicht mehr.\\
Erst klopfen, dann Säge -- der Druck sitzt, wo er will.
\end{baustein}
\end{konzept}

\begin{konzept}{3.3}{Zerlegen und Zuschneiden}
\textbf{Definition:} Zerlegen ist das Auftrennen des gefällten Stammes in transportfähige, verwendbare Abschnitte: Ablängen nach Maß, Spalten nach Fasern, Entasten gegen die Faserrichtung.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Spannung: Liegt der Stamm auf zwei Auflagern oder einer? Ein Auflager heißt Druck- und Zugseite bestimmen (Kerbohrprobe).
  \item Maß: Abschnittlängen vor dem Schnitt festlegen (Feuer 25/33 cm, Bauholz nach Konzept 5.1).
  \item Werkzeugplatz: Säge und Axt in Reichweite, niemals im Schnittbereich ablegen.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Schnittflächen: senkrecht zur Faser, keine Faserrisse über 5 mm am Rand.
  \item Ausbeute: Nutzholz-Anteil über 60 \% (Faustwert); Rest dokumentieren.
  \item Sicherheit: Kein Schnellverschluss durch Spannung; Schnitt endet mit erhobenem Oberkörper.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Spannungsholz (gedrehter Stamm, eingeklemmter Ast) spaltet unvorhersehbar. Wo der Spalt abweicht, aufhören, neu ansetzen 10 cm daneben; Gewalt erzeugt Rückschlag.

\subsection{Tabelle: Schnittspannung erkennen (Tab. 3.3)}
\begin{tabular}{p{3.6cm}p{4cm}p{4.8cm}}
\toprule
Lage des Stammes & Spannung & Schnitt-Reihenfolge \\
\midrule
Zwei Auflager, Mitte frei & Zug oben, Druck unten & Von oben: Schnitt öffnet sich; Säge nicht einklemmen lassen \\
Ein Auflager am Ende & Druck am Auflager & Schnitt auf der Unterseite zuerst, dann oben \\
Eingeklemmt (unter Ast) & Druck groß & Spreize setzen, niemals unter Last sägen \\
Hängend (an Nachbarstamm) & unklar & nicht zerlegen, Seil-Zug von außen, Konzept 8.2 \\
\bottomrule
\end{tabular}

\subsection{Schritte: Entasten und Ablängen}
\begin{enumerate}
  \item Astfolge vom Stammfuß zur Krone arbeiten, immer von oben nach unten schneiden.
  \item Astansatz vollständig entfernen (Bart nie stehen lassen: Hartholz-Verletzung beim Handling).
  \item Längen abmessen, mit Kerbe markieren, Schnitt sauber führen; Sägeblatt nie durchbiegen.
  \item Abschnitte stapeln: erste Lage quer auf zwei Kanthölzern, Folgelagen kreuzweise.
  \item Risskontrolle: Abschnitte mit Längsriss über 30 cm separat markieren („nicht tragend").
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Säge öffnet, Spalt drückt -- prüfe erst, was passiert.\\
Bart am Ast ist ein Dolch: entfernen.\\
Kreuzweise Stapeln bringt Luft, dicht Stapeln bringt Fäule.
\end{baustein}
\end{konzept}

\begin{konzept}{3.4}{Trocknen und Lagern}
\textbf{Definition:} Trocknen ist die langsame Feuchte-Reduktion von Holz durch Luftzug, bevor es verbaut oder verbrannt wird; Lagern ist die Aufbewahrung gegen Regen, Bodenfeuchte und Schädlingszugriff.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Auflage: Stapel 20 cm über Boden auf Kantholz oder Stein.
  \item Abdeckung: Dach über Stapel, Seiten offen für Luftzug.
  \item Zeit: Weichholz 6 bis 12 Monate, Hartholz 12 bis 24 Monate (Faustwerte) bis Feuchte unter 20 \%.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Feuchte-Wiegeprobe: Bohrspan wiegen, 2 h bei 105 °C trocknen (oder Ofenrestwärme), wieder wiegen; Wassergehalt berechnen (Formel: (frisch minus trocken) geteilt durch trocken mal 100).
  \item Rissbild: Trocknungsrisse an den Enden unter 10 cm Länge sind normal.
  \item Geruch: Keine Schimmel-Gerüche im Stapelinneren.
\end{enumerate}

\textbf{Ehrliche Grenzen:} In Regen-Klimaten (etwa nördliche Seeküsten, örtlich prüfen) erreicht Holz ohne Ofen kaum 15 \%. Für Präzisions-Fugen (Konzept 5.1) gilt nur Ofen- oder Innenraum-Trocknung als sicher.

\subsection{Tabelle: Lagerorte Stadt/Land (Tab. 3.4)}
\begin{tabular}{p{3.6cm}p{4.4cm}p{4.4cm}}
\toprule
Kriterium & Stadt & Land \\
\midrule
Ort & Hinterhof, Keller-Außenwand trocken & Scheunenseite mit Wetterseite abgedeckt \\
Auflage & Palettenroste, Steinplatten & Kanthölzer, Bahnschwellen \\
Abdeckung & Wellblech, Plane 10 cm Luftabstand & Bretterdach, Schindeln \\
Zugriff & abschließbar, Inventarliste (Vorlage A.1) & Hofregel, Nachbarschafts-Einblick \\
\bottomrule
\end{tabular}

\subsection{Schritte: Stapel anlegen}
\begin{enumerate}
  \item Boden 20 cm auflagern; zwei Kanthölzer parallel, 60 bis 80 cm Abstand.
  \item Erste Lage Bretter/Rundholz mit 1 cm Luftspalt nebeneinander.
  \item Zweite Lage quer oder um 90° gedreht; Ende versetzen zum Lüften.
  \item Oberste Lage mit Abdeckung, 10 cm Überstand je Seite, offene Stirnseiten.
  \item Feuchtemess-Protokoll je Stapel in Vorlage A.5 führen; alle 4 Wochen wiegen.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Boden fuchtet: 20 cm Luft unterm Stapel, immer.\\
Regen von oben, Luft von der Seite.\\
Ein Schimmelgeruch im Stapel heißt: umschichten, sofort.
\end{baustein}
\end{konzept}

\section{Kapitel-Checkliste: Das Holz}
\begin{checkliste}
  \item ☐ Jeder gefällte Baum war auf Klang, Wuchs und Feuchte geprüft (Konzept 3.1).
  \item ☐ Fallrichtung, Fluchtwege und zweite Person waren vor dem Schnitt gesichert.
  \item ☐ Fallkerb tiefe ein Drittel, Bruchleiste ein Zehntel des Durchmessers.
  \item ☐ Spannungen des liegenden Stammes vor jedem Schnitt bestimmt (Tab. 3.3).
  \item ☐ Abschnittlängen vor dem Ablängen festgelegt.
  \item ☐ Stapel 20 cm über Boden, Seiten offen, Abdeckung mit Luftspalt.
  \item ☐ Feuchteprotokoll in Vorlage A.5 geführt, alle 4 Wochen.
  \item ☐ Kein frisches Holz unter tragender Last verbaut.
\end{checkliste}
