\chapter{Die Kante: Schliff und das Halten der Schneide}

\begin{warnbox}
Schleifscheiben und Wetzsteine zerbrechen bei Überdrehzahl oder falscher Montage; Splitter fliegen mit Auge-tödlicher Energie. Schleifscheiben nur mit voller Abdeckung betreiben, Seitenfläche nicht zum Drücken nutzen (Scheibe explodiert seitlich), Rissprüfung vor jedem Einsatz: Klopfprobe, heller Klang Pflicht. Scharfe Klingen niemals offen in Werkstattkisten oder Rucksäcken tragen -- jede Klinge, die man nicht sieht, trifft die Hand, die sie sucht. Nach jedem Schneiden: Klinge einstülpen oder einstecken, bevor das Werkstück abgelegt wird.
\end{warnbox}

\begin{konzept}{4.1}{Schneidengeometrie}
\textbf{Definition:} Schneidengeometrie ist die Wahl des Schneidenwinkels je nach Werkstoff und Belastung; entscheidend sind Keilwinkel (Gesamtwinkel der Fase), Freiwinkel (Platz unter der Schneide) und Spanwinkel (Platz für das Spangut).

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Werkstoff: Weich (Fleisch, Gemüse, Weichholz) verträgt spitze Winkel; hart (Knochen, Eisennägel, Hartholz) braucht stumpfere.
  \item Belastung: Hebelwirkung (Beil) verlangt größeren Keilwinkel als Zug-Schnitt (Messer).
  \item Stahl: Härtere Stähle (Feiltest Konzept 2.3) halten spitzere Winkel, weiche Stähle rollen die Schneide um.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Schneidleistung: sauberer Schnitt ohne Quetschen am Testmaterial.
  \item Standzeit: Anzahl Schnitte bis zur nächsten Nachschärfung notieren (Faustwert: Axt 4 Stunden Holzarbeit, Küchenmesser 1 Woche Kochen).
  \item Ausbruchsfreiheit: Unter 10-facher Lupe keine Schneiden-Ausrisse sichtbar.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Winkel kleiner als 15° halten nur Edelstahl-Feinklingen; jede Feldklinge unter 20° rollt um und wird schnell stumpf. Ohne Luge bleibt Ausbruch unsichtbar -- Lupe (10×) in die Werkzeugkiste (Konzept 8.1) legen.

\subsection{Tabelle: Schneidenwinkel nach Einsatz (Tab. 4.1)}
\begin{tabular}{p{3.8cm}p{2.6cm}p{2.6cm}p{4.2cm}}
\toprule
Klinge & Keilwinkel & Schärfwinkel je Seite & Begründung \\
\midrule
Küchenmesser, weich & 20 bis 30° & 10 bis 15° & sauberer Zug-Schnitt \\
Feldmesser, Allrounder & 30 bis 40° & 15 bis 20° & Stabilität gegen Drehmoment \\
Beil, Axt (Holz) & 30 bis 40° & 15 bis 20° & Hebelkraft, Prallholz \\
Hackmesser, Knochen & 40 bis 60° & 20 bis 30° & Stumpf schlägt, spitz bricht \\
Bohrer, Stemmeisen & 70 bis 90° & -- & drückt statt schneidet \\
\bottomrule
\end{tabular}

\subsection{Schritte: Schneide beurteilen}
\begin{enumerate}
  \item Klinge unter helles Licht halten; Schneide entlangführen und Glanzlichter suchen: Glanz = Stumpfheit oder Ausbruch.
  \item Fingernagel-Test senkrecht auflegen; rutscht die Schneide ab, ist sie scharf; kerbt sie das Nagelbett, stumpf.
  \item Probeschnitt am Prüfstück (Papier für feine Klingen, Weichholz für Äxte).
  \item Ergebnis in Vorlage A.5 notieren; erst wenn die Bewertung dreimal bestanden, Klinge in den Arbeitsbestand.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Spitze schneidet, stumpfe hält: Wähle nach Werkstoff.\\
Glanz an der Kante ist die Vorankündigung des Ausbruchs.\\
Der Fingernagel ist das billigste Prüfgerät.
\end{baustein}
\end{konzept}

\begin{konzept}{4.2}{Schleifen mit Bordmitteln}
\textbf{Definition:} Schleifen ist das Abtragen von Stahl an der Schneide mit steigender Körnung (grob formen, fein glätten), bis die Schneide unter dem Winkel der Tab. 4.1 eine gratfreie Kante trägt.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Stein: Grob (etwa 80 bis 200 Körnung, Sandstein), Mittel (300 bis 600, Novakulit), Fein (über 1000, Schiefer); örtlich prüfen, was verfügbar ist.
  \item Winkelhilfe: Winkellehre aus Pappe nach Tab. 4.1 ausschneiden; ohne Lehre bleibt der Winkel ungleich.
  \item Schmiermittel: Wasser für Natursteine, Öl (Konzept 7.2) für Öhlsteine; nie mischen auf demselben Stein.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Gratkontrolle: Auf der Gegenseite fühlbarer Grat, dann beidseitig abgezogen (Ziehleiste, Leder).
  \item Winkelkonstanz: Nach zehn Zügen ist die Fase gleich breit über der Klinge.
  \item Schnitttest: Papier in einem Zug, Haar am Arm unter leichtem Zug.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Grobe Betonsteine oder Ziegel schleifen ungleichmäßig und ziehen Wärme in die Schneide -- nur für Beile und Äxte, nie für feine Klingen. Schwertsäge- und Sägeblatt-Schärfung braucht Feile und Vorrichtung (Konzept 6.3), nicht Wetzstein.

\subsection{Tabelle: Schleifweg nach Werkzeug (Tab. 4.2)}
\begin{tabular}{p{3.6cm}p{3.8cm}p{4.8cm}}
\toprule
Werkzeug & Erste Stufe & Zweite und dritte Stufe \\
\midrule
Messer (Feld, Küche) & Grobstein 20 Züge je Seite, Winkel 15° & Mittelstein 10 Züge, Feinstein 5 Züge, Leder abziehen \\
Axt, Beil & Grobstein oder Feile, runde Fase & Mittelstein, Winkel 20°; Leder-Finish \\
Sichel, Sense & Flattstift-Hämmer, dann Wetzstein & Abziehen mit Blechwinkel 15°; Sensen-Keil auf Metall \\

\bottomrule
\end{tabular}

\subsection{Schritte: Messer schleifen (Wasserstein)}
\begin{enumerate}
  \item Stein 10 Minuten in Wasser legen; Luftblasen aufhören zu steigen = wassergesättigt.
  \item Winkelhilfe auflegen; Klinge im Winkel der Tab. 4.1 ansetzen.
  \item 20 Züge je Seite im Wechsel, Druck nur in Zugrichtung, nie schieben.
  \item Grat-Prüfung mit Daumennagel an der Schneide quer (vorsichtig); fühlbarer Grat auf beiden Seiten = Stadium 1 geschafft.
  \item Mittelstein 10 Züge, Feinstein 5 Züge je Seite.
  \item Abziehen auf Leder mit Polierpaste (oder reiner Leder, 20 Züge).
  \item Schnitttest nach Tab. 4.2, Protokoll in Vorlage A.5.
\end{enumerate}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-4-1}
\caption{Abb. 4.1 -- Schleifwinkel: Keilwinkel, Fase, Freiwinkel; Winkelhaltbarkeit auf dem Stein}
\end{figure}

\begin{baustein}
\textbf{Merksätze.}\\
Erst Grob, dann Fein -- umgekehrt ist Arbeit ohne Ende.\\
Der Grat muss weg, sonst schneidet die Klinge, als wäre sie stumpf.\\
Fühlbarer Grat an beiden Seiten: Jetzt Feinstein, nicht mehr Grob.
\end{baustein}
\end{konzept}

\begin{konzept}{4.3}{Scharf halten im Feld}
\textbf{Definition:} Scharf halten ist das tägliche Nachziehen der Schneide mit Feinstein oder Leder, bevor Stumpfheit entsteht -- 60 Sekunden gegen 15 Minuten Nachschliff.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Taschenausstattung: Feinstein (Körnung über 1000, Postkartengröße) oder Lederstreifen 30 cm.
  \item Anlass: Nach jedem Arbeitstag, nach Schnitt in Sand, Erde oder Knochen sofort.
  \item Zustand: Klinge trocken, fettfrei (Fett nach Konzept 7.2 erst nach dem Nachziehen).
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Schnelltest: Papier einhändig, sauber getrennt.
  \item Winkelgleichheit: Fase gleich breit über der Länge.
  \item Rhythmus: Nachzieh-Intervall im Werkstatt-Logbuch (Vorlage A.5) eingetragen.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Nachziehen bessert nur Mikro-Stumpfheit; eine geknickte oder ausgerollte Schneide braucht den vollen Weg nach Konzept 4.2. Leder ersetzt den Stein nicht, es poliert.

\subsection{Tabelle: Nachzieh-Rhythmus (Tab. 4.3)}
\begin{tabular}{p{3.6cm}p{3.6cm}p{4.8cm}}
\toprule
Nutzung & Nachziehen & Voller Schliff (Konzept 4.2) \\
\midrule
Küchenmesser, täglich & 5 Züge Leder vor dem Einlagern & alle 4 Wochen (Faustwert) \\
Feldmesser, Wochenend-Einsatz & 10 Züge Leder nach Einsatz & alle 3 Einsätze \\
Axt, ein Tag Holzarbeit & 5 Züge Stein, leichte Fase & nach 4 Arbeitstagen (Faustwert) \\
Sichel, Mäharbeit & 5 Minuten Wetzstein am Feld & nach 2 Tagen Schärfung mit Flattstift \\
\bottomrule
\end{tabular}

\subsection{Schritte: Feld-Nachziehen}
\begin{enumerate}
  \item Klinge reinigen (Lappen, Wasser), trocknen.
  \item Leder oder Stein flach halten, Klinge im Winkel der Tab. 4.1 aufsetzen.
  \item 5 bis 10 Züge je Seite, leichter Druck, gleichbleibender Winkel.
  \item Papier-Schnelltest; bei Riss statt Schnitt: Rückkehr zum vollen Schliff (Konzept 4.2).
  \item Klinge einfetten (Konzept 7.2) und einstülpen.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Sechzig Sekunden am Tag schlagen fünfzehn Minuten am Monatsende.\\
Sand in der Schneide: sofort nachziehen, nicht erst zu Hause.\\
Niemals auf Metall eines anderen prüfen -- das stumpft beide.
\end{baustein}
\end{konzept}

\section{Kapitel-Checkliste: Die Kante}
\begin{checkliste}
  \item ☐ Jede Klinge hat einen festgelegten Zielwinkel (Tab. 4.1) in der Inventarliste.
  \item ☐ Schleifweg je Werkzeug nach Tab. 4.2 an der Werkstattwand ausgehängt.
  \item ☐ Winkelhilfe je Klinge vorhanden und benutzt.
  \item ☐ Nachzieh-Rhythmus nach Tab. 4.3 in den Tagesablauf eingebaut.
  \item ☐ Grat vor dem Feinschliff geprüft und entfernt.
  \item ☐ Kein Schleifen ohne Prüfschnitt und Protokoll (Vorlage A.5).
  \item ☐ Klingen nie offen getragen; Einstülpung nach jedem Schnitt.
  \item ☐ Schleifscheiben nur mit Abdeckung, Klopfprobe vor jedem Einsatz.
\end{checkliste}
