\chapter{Die Fuge: Zapfen, Loch, Keil und Knoten}

\begin{konzept}{5.1}{Zapfen und Loch}
\textbf{Definition:} Die Zapfenverbindung ist das Ineinanderschieben von Zapfen (Hervorragung am einen Teil) und Loch (Vertiefung im anderen); sie trägt Druck, nicht Zug, und braucht Passsitz oder Keil (Konzept 5.2) gegen Wackeln.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Holz:tragende Zapfen aus Hartholz oder feinjährigem Nadelholz; Feuchte unter 15 \% (Konzept 3.4).
  \item Maß: Zapfendicke ein Drittel der Bauteilbreite (Faustwert); Zapfenlänge das 1,5-Fache der Dicke.
  \item Werkzeug: Stechbeitel, Holzhammer, Bohrer mit Größe passend (Durchmesser knapp unter Lochweite).
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Passung: Zapfen sitzt ohne Hammer nach Handdruck halb ein.
  \item Stand: Verbindung wackelt nicht unter 20 kg Querlast am Bauteilende (Prüfzelt-Stange).
  \item Zerlegbarkeit: Verbindung lösbar ohne Zerstörung (für Reparatur nach Konzept 6.2).
\end{enumerate}

\textbf{Ehrliche Grenzen:} Zapfen aus frischem Holz schwinden beim Trocknen und wackeln nach 3 Monaten. Eine Zapfenverbindung ohne Verkeilung ist eine temporäre; verkeile nach Konzept 5.2, wenn sie Last hält.

\subsection{Tabelle: Grundmaße der Zapfenverbindung (Tab. 5.1)}
\begin{tabular}{p{3.6cm}p{3.4cm}p{4.6cm}}
\toprule
Bauteilbreite & Zapfendicke & Zapfenlänge \\
\midrule
30 mm & 10 mm & 15 mm \\
45 mm & 15 mm & 22 mm \\
60 mm & 20 mm & 30 mm \\
90 mm & 30 mm & 45 mm \\
120 mm & 40 mm & 60 mm \\
\bottomrule
\end{tabular}

\subsection{Schritte: Zapfen schneiden (Stechbeitel)}
\begin{enumerate}
  \item Maße nach Tab. 5.1 auf das Bauteilende übertragen; Kanten mit Reißnadel oder Messer anreißen.
  \item Schulterlinie um das ganze Werkstück anreißen; Tiefe mit zwei Schnitten vorstechen.
  \item Zapfenwangen abwechselnd von beiden Seiten stechen, Stecheisen nie quer über die Faser.
  \item Probefassung: Zapfen in Probe-Loch schieben; bei Widerstand Schultern nachputzen, nicht die Wanke abschneiden.
  \item Fasen an den Zapfenecken 1 mm breit anlegen -- verhindert Splittieren beim Einpassen.
\end{enumerate}

\subsection{Schritte: Loch stechen}
\begin{enumerate}
  \item Lochmitte anreißen; Umrisse der Lochweite auf beide Seiten des Bretts übertragen.
  \item Bohrer (Durchmesser knapp unter Lochweite) mittig vorbohren, Tiefe = Zapfenlänge + 2 mm.
  \item Restwand mit Stechbeitel herausarbeiten; Beitel flach auf die Anrisslinie stellen, zuerst senkrecht stoßen.
  \item Lochboden säubern, Kanten brechen (0,5 mm Fase).
  \item Probefassung, dann Montage mit Holzhammer und Wachs als Gleitmittel (Konzept 7.2).
\end{enumerate}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-5-1}
\caption{Abb. 5.1 -- Zapfenverbindung: Anriss, Zapfen, Loch, verkeilte Ausführung}
\end{figure}

\begin{baustein}
\textbf{Merksätze.}\\
Zapfen ein Drittel der Breite, Länge anderthalb mal die Dicke.\\
Erst Probe-Loch, dann echtes Loch.\\
Hammer nur mit Wachs oder Wasser als Gleitmittel.
\end{baustein}
\end{konzept}

\begin{konzept}{5.2}{Keil und Verkeilung}
\textbf{Definition:} Ein Keil ist ein keilförmiges Holzteilstück, das durch Eintreiben eine spielfreie Verbindung erzeugt; er wirkt nur in Faserrichtung Druck und muss gegen Ausreißen gesichert sein.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Material: Keil aus Hartholz, Faserrichtung parallel zur Keilflanke; Faser quer = Keil bricht.
  \item Keilwinkel: unter 10° (Faustwert) -- steiler Keil sprengt das Loch, flacher rutscht er.
  \item Keilspalt: Ist Platz für den Keil da (Zapfenschlitz, Lochschräge) oder muss er geschnitten werden?
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Sitz: Keil sitzt nach 2 Schlägen fest, Endzapfen endet bündig mit der Kante.
  \item Spaltfreiheit: Keil ist nicht durchgebrochen; Flanken pressen auf ganzer Länge.
  \item Festigkeit: Verbindung zieht sich unter 10 kg Querlast nicht auseinander.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Keile lösen sich in weichem, feuchtem Holz nach Wochen. Prüfe verkeilte Verbindungen alle 3 Monate (Nachschlagetabelle Konzept 6.3); ein nachgestellter Keil hält länger als ein neu geschlagener an der falschen Stelle.

\subsection{Tabelle: Keiltypen und Einsatz (Tab. 5.2)}
\begin{tabular}{p{3.2cm}p{4.2cm}p{4.4cm}}
\toprule
Keiltyp & Form & Anwendung \\
\midrule
Futterkeil (Spaltkeil) & lang, beidseitig & Holz spalten (Konzept 3.3) \\
Montagekeil (Treiber) & flach, parallel & Zapfen verkeilen, Lagerspiel raus \\
Stellkeil (Klemmkeil) & dünn, lang & Möbel, Zelte, Schnallen nachziehen \\
Runder Keil (Stiftkeil) & zylindrisch geschlitzt & Bohrungen sichern, Griffmontage \\
\bottomrule
\end{tabular}

\subsection{Schritte: Zapfen verkeilen}
\begin{enumerate}
  \item Zapfenspitze oder Lochwand auf 2 mm anwärken (Werkzeug: Säge, 2 Schnitte kreuzweise).
  \item Keil in Zapfenschlitz einpassen, Spitze 2 mm vor Zapfenende.
  \item Keil mit 2 Schlägen einschlagen; Widerstand prüfen, nach drittem Schlag stoppen (sprengt das Werkstück).
  \item Überstehende Keil- und Zapfenebene abschneiden oder stehen lassen als Reparaturansatz.
  \item Sichtmarkierung auf Keilkopf: „Wartung nach Tabelle 6.2 alle 3 Monate".
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Unter zehn Grad: Der Keil zieht, über zehn sprengt er.\\
Zwei Schläge genügen -- der dritte bricht.\\
Keilholz in Faserrichtung, sonst ist es nur ein Splitter.
\end{baustein}
\end{konzept}

\begin{konzept}{5.3}{Nägel, Holznägel, Dübel}
\textbf{Definition:} Nägel (Eisen, geschmiedet nach Konzept 2.4), Holznägel (aus Hartholz) und Dübel verbinden Bauteile quer zur Faser; sie sind schneller als Zapfen, aber schwächer auf Zug und nicht zerstörungsfrei lösbar.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Zugrichtung: Nägel halten Scher-, nicht Zuglast; bei Zuglast Schraubenform oder Zugband verwenden.
  \item Vorbohren: Weiches Brett splittert ohne Vorbohrung (Durchmesser 0,7× Nagel; Faustwert).
  \item Nagellänge: 2,5× Dicke des oberen Bretts, aber nicht ganz durch das untere (oder sauber umgebogen).
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Sitz: Nagelkopf sitzt auf, ohne Faser einzudrücken.
  \item Splitterfreiheit: kein Riss am Brett über 10 mm.
  \item Löseprobe: Nagel mit Zange gestreckt und herausgezogen ohne Brettbruch = gut genagelt.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Geschmiedete Handnägel brechen bei Biegung -- öfter nachschmieden, jedes Mal Materialverlust. Holznägel halten nur in trockenem Holz; sie quellen mit der Feuchte und sitzen nach zwei Jahren besser als am ersten Tag.

\subsection{Tabelle: Verbindungswahl nach Lastfall (Tab. 5.3)}
\begin{tabular}{p{3.6cm}p{3.6cm}p{4.4cm}}
\toprule
Lastfall & Verbindung & Grund \\
\midrule
Druck, ruhend & Zapfen oder Fläche & Zapfen trägt Druck am besten \\
Zug, ruhend & Zugband, Keil, Schlinge & Nagel zieht sich aus \\
Zug, wechselnd & Schraube oder genagelt mit Bogen & Bogen wirkt wie Feder \\
Biege, oft gelöst & Keil oder Bolzen & lösbar für Reparatur (Konzept 6.2) \\
Dreh, stark & Doppelzapfen mit Keil & einzelner Zapfen verdreht \\
\bottomrule
\end{tabular}

\subsection{Schritte: Holznagel herstellen und setzen}
\begin{enumerate}
  \item Hartholzstab 8 mm quadratisch, Länge = Bauteildicke + 40 mm, in Spaltholz spalten (Konzept 3.3).
  \item Spitze 15 mm an vier Seiten behauen, Endquerschnitt 5 mm.
  \item Bohrung 6 mm vorbohren (leicht kleiner als Schaft, größer als Spitze).
  \item Holznagel eintreiben; Überstand abbrechen, nicht absägen (Säge verletzt das Brett).
  \item Kopf-Markierung mit Farbe oder Kerbe: Nagel ist zerstörungsfrei nur mit Bohrer lösbar.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Nagel hält Schub, niemals Zug.\\
Vorbohren spart Bretter: 0,7-facher Durchmesser.\\
Holznagel wächst mit dem Regen -- Eisen rostet mit ihm.
\end{baustein}
\end{konzept}

\begin{konzept}{5.4}{Knoten und Seilverbindungen}
\textbf{Definition:} Knoten sind form-schlüssige Seilverbindungen, die unter Last halten und ohne Beschädigung lösbar bleiben; drei Knoten decken 90 \% der Feldaufgaben ab (Faustwert): Palstek (feste Öse), Webeleinstek (Belegen an Pfosten), Kreuzknoten (Enden verbinden, gleiche Stärke).

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Seilmaterial: Naturfaser (Hanf, Sisal) gut knotbar, glattes Kunststoffseil rutscht -- Zusatzknoten oder Klemme nötig.
  \item Durchmesser: Mindest-Breaklast 5× der geplanten Last (Faustwert, ohne Tabelle ist jede Angabe geraten).
  \item Zustand: Seil ohne Kernbrüche (durchlaufende Prüfung mit der Hand, 30 cm Abstand).
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Halt: Knoten rutscht nicht unter 2 Minuten Volllast.
  \item Lösbarkeit: Nach Entlastung mit einer Hand lösbar; wenn nicht, falsch geknüpft.
  \item Seilschonung: Keine scharfe Kante im Knotenverlauf (Kanten mit Lappen umwickeln).
\end{enumerate}

\textbf{Ehrliche Grenzen:} Seil ist ein Verschleißteil: UV, Nässe und Kanten setzen die Tragfähigkeit je nach Nutzung in Monaten herab. Für Lasten über Körpergewicht nur Seil mit bekannter Historie (Vorlage A.1) verwenden.

\subsection{Tabelle: Knotenauswahl (Tab. 5.4)}
\begin{tabular}{p{3.4cm}p{4.2cm}p{4.2cm}}
\toprule
Aufgabe & Knoten & Fehler \\
\midrule
Feste Öse um Balken & Palstek & Überhand statt Halber Schlag: nicht lösbar \\
Belegen am Pfosten & Webeleinstek (zwei Halbe Schläge) & nur ein Schlag: rutscht unter Last \\
Zwei Enden verbinden & Kreuzknoten (bei gleichem Durchmesser) & Schifferknoten bei unterschiedlich: rutscht \\
Zelt abspannen & Halber Schlag plus Spannkluppe & ohne Klffe: Leine wandert \\
Bündel schnüren & Zimmermannsschlag & Kreuzknoten: zu schwer zu lösen \\
\bottomrule
\end{tabular}

\subsection{Schritte: Palstek}
\begin{enumerate}
  \item Seil in der Hand: kleine Schlinge („Kaninchenloch") drehen.
  \item Ende („Kaninchen") von unten durch das Loch führen.
  \item Um die stehende Part („Baum") herumführen.
  \item Wieder zurück ins Loch führen; nicht straff ziehen, sondern formen.
  \item Probebelastung mit Körpergewicht (nur bei gesichertem Stand, Konzept 1.1); Lösungstest mit einer Hand.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Knoten muss halten und sich lösen -- eins ohne das andere ist ein Fehler.\\
Fünfmal geplant Last, dann trägt die Seil-Leine.\\
Kanten zerfressen Seile schneller als Lasten.
\end{baustein}
\end{konzept}

\section{Kapitel-Checkliste: Die Fuge}
\begin{checkliste}
  \item ☐ Zapfenmaße nach Tab. 5.1 vor dem Anriss übertragen.
  \item ☐ Jede tragende Zapfenverbindung ist verkeilt (Konzept 5.2).
  \item ☐ Keile aus Hartholz in Faserrichtung, Winkel unter 10°.
  \item ☐ Verbindungswahl nach Lastfall (Tab. 5.3), nicht nach Gewohnheit.
  \item ☐ Nägel vorgebohrt (0,7×), Nagellänge 2,5× oberes Brett.
  \item ☐ Palstek, Webeleinstek, Kreuzknoten aus dem Kopf und unter Last geprüft.
  \item ☐ Seile mit unbekannter Historie tragen keine Lasten über Körpergewicht.
  \item ☐ Verkeilte Verbindungen im Wartungsturnus (Konzept 6.3) geprüft.
\end{checkliste}
