\chapter{Die Werkstatt: Ordnung als Werkzeug und das Flicken als Methode}

\begin{konzept}{6.1}{Ordnungssystem}
\textbf{Definition:} Das Ordnungssystem der Werkstatt ordnet jedem Werkzeug, jedem Werkstoff und jedem angefangenen Stück einen festen Platz zu -- so, dass Fehlendes in unter 30 Sekunden auffällt, bevor die Arbeit beginnt.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Platzzwang: Jedes Werkzeug hat eine Umriss-Schablone (Karton, Farbe) an der Wand; Lücke = fehlend.
  \item Fehl-Prüfung: Beim Verlassen der Werkstatt Blick an die Wand -- jede Lücke wird gemeldet (Konzept 1.2).
  \item Fluss: Werkzeuge zwischen Entnahme und Rückgabe auf einer Ablage („Werkbank-Mitte"), nie im Regal.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Suchzeit: Unter 30 Sekunden für jedes Werkzeug (Zeitprobe).
  \item Fehlquote: Keine Werkstatt-Stunde endet mit einer ungemeldeten Lücke.
  \item Unfallfreiheit: Kein Werkzeug lag in der letzten Woche auf dem Fußboden.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Ordnungssysteme zerfallen, wenn mehr als drei Personen ohne Verabredung die Werkstatt nutzen. Vereinbare Nutzungsfenster (Stadt: Nachbarschaftsplan, Land: Hofplan) und einen Werkstatt-Verwalter.

\subsection{Tabelle: Zonen der Werkstatt (Tab. 6.1)}
\begin{tabular}{p{3.2cm}p{4.4cm}p{4.4cm}}
\toprule
Zone & Inhalt & Regel \\
\midrule
Wand & Handwerkzeuge an Schablonen & Entnahme nur in benutzte Hand \\
Werkbank-Mitte & Werkstück, laufende Arbeit & nach Arbeitstag vollständig geräumt \\
Ablage-Rohstoff & Bauholz, Bleche, Leder & nur voll sorterter Zugang \\
Gefahren-Ecke & Scharfes, Brennbares, Giftiges & kindersicher, Zugriff nur mit Anmeldung \\
Warte-Ecke & angefangene Reparaturen (Vorlage A.2) & sichtbar, mit Frist \\
\bottomrule
\end{tabular}

\subsection{Schritte: Werkstatt in eine Stunde ordnen}
\begin{enumerate}
  \item Alles von der Werkbank nehmen; nur zurücklegen, was in 30 Tagen benutzt wurde.
  \item Werkzeuge an die Wand: häufig genutztes auf Griffhöhe, seltenes oben, schweres unten.
  \item Schablonen aus Karton schneiden, mit Farbe nachzeichnen; Werkzeug-Nummer der Inventarliste (Vorlage A.1) daneben schreiben.
  \item Zonen nach Tab. 6.1 markieren (Kreide, Farbe): fünf Flächen, fünf Nummern.
  \item Warte-Ecke mit Fristen einrichten; jedes wartende Stück erhält Vorlage A.2 am Revers.
  \item Stand-Kasten ausfüllen: Datum, Verantwortlicher, nächste Prüfung.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Jede Lücke an der Wand ist eine Frage: Wo ist das Werkzeug?\\
Die Werkbank ist ein Arbeitsplatz, kein Lager.\\
Fünf Zonen, fünf Nummern -- wer nicht weiß wo, weiß auch nicht womit.
\end{baustein}
\end{konzept}

\begin{konzept}{6.2}{Flicken als Methode}
\textbf{Definition:} Flicken ist die systematische Reparatur: erst Schadenanalyse, dann Entscheidung flicken oder ersetzen, dann Ausführung mit geprüftem Material, dann Rückmeldung in die Inventarliste -- in dieser Reihenfolge, immer.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Schadensbild: Ganzteil prüfen, nicht nur die Bruchstelle (Risse laufen weiter; Nachbarstellen mitprüfen).
  \item Wiederhol-Frage: Ist der Schaden zum zweiten Mal an derselben Stelle? Dann Ursache beseitigen, nicht Symptom flicken.
  \item Material: Flickstück gleicher Art oder stärker; „ähnlich" ist eine Absage.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Festigkeit: Flickstelle hält 1,5× der Nutzlast (Prüflast).
  \item Sichtbarkeit: Flickstelle markiert (Farbe, Kerbe), damit die nächste Prüfung sie findet.
  \item Protokoll: Schaden, Ursache, Maßnahme in Vorlage A.2; Wiederholfehler erkennbar.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Manche Schäden sind Grenzfälle: Faustregel -- wenn das Flickstück mehr Zeit kostet als ein Neubau (Konzept 2.4, 3.3), und der Neubau gleicher Qualität möglich ist, dann flicken nur aus Ehrbarkeit vor dem Material, nicht aus Vernunft.

\subsection{Tabelle: Flick-Entscheidung (Tab. 6.2)}
\begin{tabular}{p{3.6cm}p{4.2cm}p{3.6cm}}
\toprule
Befund & Entscheidung & Begründung \\
\midrule
Riss, einmal, Rand & flicken (Konzept 5.1 bis 5.4) & Material günstig \\
Bruch, einmal, Kern & ersetzen, Material prüfen & Flickstelle wird Schwachstelle \\
Bruch, mehrfach, gleiche Stelle & Ursache suchen, Konstruktion ändern & Symptomflicken versagt \\
Materialermüdung (Rost, Fäule) & Teil ersetzen, Nachbarn prüfen & Ermüdung kommt in Wellen \\
Unbekannter Werkstoff & Probeflicken an Probe-Teil & unbekanntes Material bricht überraschend \\
\bottomrule
\end{tabular}

\subsection{Schritte: Reparatur nach Vorlage A.2}
\begin{enumerate}
  \item Schaden beschreiben in einem Satz: Teil, Stelle, Art (Riss, Bruch, Verschleiß).
  \item Ganzteil prüfen; Nachbarstellen mit Zustandsliste nach Tab. 6.2 ansehen.
  \item Entscheidung treffen und begründen (Vorlage A.2 Feld 4).
  \item Werkstoff prüfen nach Kapitel 2 (Stahl), 3 (Holz), 7 (Leder, Leim).
  \item Flickstelle vorbereiten: anfasen, reinigen, trocknen.
  \item Ausführen nach Kapitel 2 bis 5; Prüflast ansetzen (1,5×).
  \item Flickstelle markieren und Protokoll abschließen; Wartungseintrag in Turnustabelle (Konzept 6.3).
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Erst Ganzteil, dann Bruchstelle -- Risse laufen weiter.\\
Zweimal an derselben Stelle heißt: Konstruktion ändern.\\
Ein Flick ist nur fertig, wenn er markiert und protokolliert ist.
\end{baustein}
\end{konzept}

\begin{konzept}{6.3}{Wartungsrhythmus}
\textbf{Definition:} Der Wartungsrhythmus ist die Tabelle, die jedem Werkzeug und jeder Verbindung ein Prüfintervall zuordnet; geprüft wird nach Zeit oder nach Nutzung, je nachdem, was zuerst eintritt.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Vollständigkeit: Jedes Inventar-Stück (Vorlage A.1) hat ein Intervall.
  \item Realismus: Intervalle aus Erfahrung, nicht aus Wunschdenken; erstnutzung protokollieren.
  \item Zeitanker: Prüftage an Ereignisse koppeln (Monatsanfang, Jahreszeiten), nicht an Erinnerung.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Vorfall-Quote: Kein Ausfall ereignete sich seit der letzten geplanten Prüfung.
  \item Aufwand: Wartungsstunden unter 5 \% der Nutzungsstunden (Faustwert).
  \item Verlässlichkeit: Keine Prüfung wurde länger als 20 \% des Intervalls überschritten.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Verschleiß folgt keinen Kalendern bei intensiver Nutzung. Nutze Doppel-Auslösung: Intervall ODER Nutzungszähler (Kapitel-Checklisten der Kapitel 2 bis 5).

\subsection{Tabelle: Wartungsturnus der Kernwerkzeuge (Tab. 6.3)}
\begin{tabular}{p{3.2cm}p{3.4cm}p{5.2cm}}
\toprule
Objekt & Intervall & Prüfpunkte \\
\midrule
Hammer, Axt & 3 Monate & Stielriss, Sitz, Schneide (Konzept 4.3) \\
Säge, Handsäge & 2 Monate & Zahnbild, Spannung, Griff \\
Zangen & 6 Monate & Gelenköl, Backenverschleiß \\
Schmiedefeuer & nach je 10 Stunden & Rohrfreiheit, Aschenfall, Standfestigkeit \\
Holzstapel & 4 Wochen & Feuchte (Vorlage A.5), Geruch, Abdeckung \\
Verkeilte Verbindungen & 3 Monate & Keilsitz (Konzept 5.2), Risse \\
Seile & nach jeder Nutzung & Kernbruchprüfung (Konzept 5.4) \\
Lederriemen & 3 Monate & Trockenrisse, Fettgehalt (Konzept 7.3) \\
\bottomrule
\end{tabular}

\subsection{Schritte: Prüftag durchführen}
\begin{enumerate}
  \item Inventarliste (Vorlage A.1) nehmen, Spalte „nächste Prüfung" sortieren.
  \item Jede fällige Zeile abarbeiten; Prüfpunkte der linken Spalte in Tab. 6.3 nachgehen.
  \item Befund eintragen: „i. O." oder Mangel mit Maßnahme.
  \item Mängel an Konzept 6.2 übergeben (Vorlage A.2, Warte-Ecke).
  \item Neue Intervalle setzen; überfällige Intervalle kürzen (Faustwert: halbieren).
  \item Stand-Kasten aktualisieren.
\end{enumerate}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-6-1}
\caption{Abb. 6.1 -- Werkstatt-Grundriss: fünf Zonen, Wege und Gefahren-Ecke}
\end{figure}

\begin{baustein}
\textbf{Merksätze.}\\
Wartung nach Tabelle, nicht nach Erinnerung.\\
Zwei Auslöser, ein Termin: Zeit oder Nutzung, was zuerst kommt.\\
Überfälliges Intervall halbiert sich.
\end{baustein}
\end{konzept}

