\chapter{Die Material-Kammer: Leim, Fett, Riemen und das Gedächtnis des Vorrats}

\begin{konzept}{7.1}{Leim selbst machen}
\textbf{Definition:} Leim verbindet Flächen stoffschlüssig; die drei Feld-Leime sind Knochenleim (Haut, Knochen, warm zu verarbeiten, wärmelöslich), Pflanzenkleister (Stärke, kalt, wasserlöslich) und Baumbast-Leim (Birkenrinde-Pech, wasserfest, spröde).

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Rohstoff: Knochen, Hautreste, Sehnen (Knochenleim); Weizen-, Roggenmehl (Kleister); Birkenrinde (Pech) -- nur unbelastete, unverdorbene Ausgangsstoffe.
  \item Werkzeuge: Topf mit Wasserbad (Knochenleim wird nie direkt über Feuer gekocht: 60 bis 70 °C), Rührlöffel, Sieb.
  \item Zielverwendung: tragende Verbindungen brauchen Knochenleim oder Pech; Papier, Stoff genügt Kleister.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Klebkraft: Zwei Holzproben 24 h verleimt, 20 kg Zug -- Trennung nur im Holz, nicht in der Fuge.
  \item Wasserfestigkeit: Probe 2 h in Wasser gelegt; Knochenleim löst sich (erwartbar), Pech nicht.
  \item Haltbarkeit: Vorrat im Kühlen, Geruchsprüfung wöchentlich (Faustwert: fauliger Geruch = weg).
\end{enumerate}

\textbf{Ehrliche Grenzen:} Knochenleim ist wärmelöslich -- bei Sonne in der Werkstatt (über 50 °C am Werkstück, Faustwert) lösen sich Verbindungen. Für Außen-Verbindungen nur Pech oder mechanische Verbindung (Kapitel 5).

\subsection{Tabelle: Leimwahl nach Einsatz (Tab. 7.1)}
\begin{tabular}{p{3.2cm}p{3.6cm}p{4.6cm}}
\toprule
Leim & Stärke & Grenze \\
\midrule
Knochenleim (warm) & hoch auf Holz, Stoff & löst sich in Wärme und Wasser \\
Pflanzenkleister & mittel auf Papier, Stoff & wasserlöslich, Schimmel-Risiko \\
Baumbast-Pech & wasserfest & spröde, bricht auf Stoß \\
Harz-Kolophonium & sehr hart & nur Innen, bei Wärme weich \\
\bottomrule
\end{tabular}

\subsection{Schritte: Knochenleim kochen}
\begin{enumerate}
  \item Rohstoffe 12 h in Wasser einweichen (Knochen grob zerkleinern, 2 bis 3 cm).
  \item Wasserbad auf 65 °C bringen; Material einfüllen, 6 bis 8 Stunden ziehen lassen (nie kochen).
  \item Flüssigkeit durch Sieb abgießen; auf Sirupdicke einengen (Tropfenprobe am Löffel).
  \item In flacher Form auskühlen lassen; in Platten trocknen, luftdicht lagern.
  \item Zur Verwendung: Platte einweichen (12 h), im Wasserbad auf 60 °C schmelzen.
  \item Leimauftrag dünn beidseitig, Werkstück 30 s pressen (Zwinge oder Keil, Konzept 5.2), 24 h trocknen.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Knochenleim kocht nie -- er zieht.\\
Dünn beidseitig ist stärker als dick einseitig.\\
Wärmelöslich heißt: Im Sommer im Schatten verleimen.
\end{baustein}
\end{konzept}

\begin{konzept}{7.2}{Fett, Öl und Wachs}
\textbf{Definition:} Fette und Öle schützen Metall gegen Rost, Holz und Leder gegen Austrocknen, und dienen als Gleitmittel; Wachs dichtet und glättet Oberflächen.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Quelle: tierisch (Talg, Schmalz -- örtlich prüfen was anfällt) oder pflanzlich (Leinöl, Raps) -- nur frische, nicht ranzige Ware.
  \item Ziel: Rostschutz braucht harzarme Öle; Holzp flea ned verharzend (Leinöl härtet aus).
  \item Vorrat: Lichtfest, kühl, Behälter dunkel und gefüllt (Sauerstoff macht ranzig).
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Schutztest: Probestück Stahl 4 Wochen im Wechselklima -- Rost nur an unbefetteten Stellen.
  \item Eindringtiefe: Öl im Holz tropft nach 10 Minuten nicht mehr ab.
  \item Verbrauch: Jede Werkstatt-Stunde unter 5 ml Öl (Faustwert); Mehrverbrauch deutet auf Fehlgebrauch hin.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Leinöl-Fettragsreste an Lappen können sich selbst entzünden (Selbstentzündung durch Härtungswärme): Öllappen nach Gebrauch ausgebreitet oder in Wasser gelagert trocknen lassen, nie zusammengeknüllt in den Abfall.

\subsection{Tabelle: Pflegemittel-Zuteilung (Tab. 7.2)}
\begin{tabular}{p{3.2cm}p{3.6cm}p{4.6cm}}
\toprule
Mittel & Anwendung auf & Rhythmus \\
\midrule
Talg oder feste Fette & Klingen, Werkzeuge & nach jeder Nutzung dünn \\
Leinöl & Holzgriffe, Werkbank & alle 3 Monate \\
Wachs (Bienenwachs, Pech) & Fugen, Gleitflächen & bei Bedarf, dünn \\
Graphit-Fett (Steinkohlen-Griß) & Schlösser, Gelenke & halbjährlich \\
\bottomrule
\end{tabular}

\subsection{Schritte: Werkzeug nach der Arbeit fetten}
\begin{enumerate}
  \item Werkzeug abwischen bis zur trockenen Klinge.
  \igen Tropfen Öl oder Streifen Talg auf Lappen auftragen; Lappen doppelt gelegt.
  \item Klinge zweimal abziehen; Öl darf nicht laufen.
  \item Holzgriff nur im Winter fetten (Sommer: Grip-Verlust).
  \item Lappen ausbreiten, Werkzeug in Schablone (Konzept 6.1) zurück.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Rost frisst Klinge schneller als Schnitt.\\
Öllappen flach oder im Wasser -- niemals geknüllt.\\
Dünner Film schützt, ölige Suppe fängt Sand.
\end{baustein}
\end{konzept}

\begin{konzept}{7.3}{Riemen und Leder}
\textbf{Definition:} Leder ist durch Gerbung konservierte Haut; Riemen, Gurte und Bänder daraus tragen Zuglast, schützen Hände und Werkzeuge und sind mit Nachfettung mehrjährig haltbar.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Zustand: Risse quer zur Zugrichtung = unbrauchbar; trockene, harte Stellen = nachfetten (Konzept 7.2).
  \item Naht: Nahtlöcher weitgenagt oder Nahtfaden brüchig = nachnähen vor Belastung.
  \item Belastung: RiemenDicke zur Last -- Faustwert Zuglast pro cm Breite bei 3 mm Dicke etwa 50 kg (Faustwert, örtlich prüfen).
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Dehnung: Unter Volllast unter 2 \% Längenzunahme (Marcierung und Messung).
  \item Nähte: Kein Loch weiter als 3 mm vom Rand.
  \item Pflege-Nachweis: Fettgehalt alle 3 Monate geprüft (Tab. 6.3).
\end{enumerate}

\textbf{Ehrliche Grenzen:} Leder fault bei Dauerfeuchte und friert spröde. Für Außen-Lasten ohne Wartung sind Seil (Konzept 5.4) oder Kette besser.

\subsection{Tabelle: Leder-Auswahl (Tab. 7.3)}
\begin{tabular}{p{3.2cm}p{3.8cm}p{4.2cm}}
\toprule
Dicke & Einsatz & Naht \\
\midrule
1 bis 2 mm & Handschutz, Umwicklung & Vorstich \\
3 bis 4 mm & Riemen, Gurte, Messerscheide & Sattlernaht \\
über 5 mm & Zuglasten, Maschinenriemen & Doppelnaht mit zwei Nadeln \\
\bottomrule
\end{tabular}

\subsection{Schritte: Riemen flicken}
\begin{enumerate}
  \item Bruchenden gerade schneiden, 2 cm Überlappung ansetzen.
  \item Überlappung aufrauen (Raspel, Schmirgel), entfetten, Knochenleim (Konzept 7.1) auftragen.
  \item Pressen 24 h, dann Sattlernaht mit gepechtem Faden alle 5 mm.
  \item Flickstelle fetten; Prüflast 1,5× (Konzept 6.2).
  \item Protokoll in Vorlage A.2; Wartungseintrag alle 3 Monate.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Risse quer zur Zugrichtung: Riemen ersetzen.\\
Fett hält Leder, Zug allein tut es nicht.\\
Nahtloch unter 3 mm Abstand reißt aus.
\end{baustein}
\end{konzept}

\begin{konzept}{7.4}{Gedächtnis des Vorrats}
\textbf{Definition:} Das Gedächtnis des Vorrats ist das Karten- und Zählsystem der Material-Kammer: Jede Karte weiß, was da ist, wie viel Mindestbestand gilt, wann es geprüft wurde und was zuerst verbraucht werden muss (erst rein, erst raus).

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Kartei: Jede Materialgruppe hat eine Bestandskarte (Vorlage A.4) mit Menge, Mindestbestand, Lagerort.
  \item Zugriffsdisziplin: Entnahme wird sofort eingetragen; wer entnimmt, zählt nach.
  \item Turnus: Bestandsprüfung monatlich, Geruch/Feuchte-Prüfung wöchentlich bei organischen Stoffen.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Vollständigkeit: Bestandszahl stimmt mit Zählung überein (Stichprobe monatlich).
  \item Mindestbestand: Kein Bestand unter Mindest ohne Nachschub-Auftrag.
  \item Verlustquote: Unter 5 \% pro Jahr durch Verderb (Faustwert).
\end{enumerate}

\textbf{Ehrliche Grenzen:} Ein Vorrats-Gedächtnis ohne Verwalter verfällt in Wochen. Benenne eine Person (Stadt: Hausgemeinschafts-Rat; Land: Hofinhaber) und einen Stellvertreter.

\subsection{Tabelle: Mindestbestände für Handwerk (Tab. 7.4)}
\begin{tabular}{p{4.2cm}p{2.6cm}p{4.2cm}}
\toprule
Material & Mindestbestand & Begründung \\
\midrule
Holzkohle (Schmiede) & 50 kg & 10 Schmiedetage \\
Knochenleim-Platten & 1 kg & 50 Reparaturen klein \\
Leinöl & 2 l & Werkzeugpflege 1 Jahr \\
Wachs & 500 g & Gleit- und Dichtflächen \\
Leder 3 mm & 1 m² & Riemen, Sicherungen \\
Nähfaden, gepicht & 100 m & 20 Flickstellen \\
Seil 10 mm, Hanf & 30 m & Abstecher, Lasten \\
\bottomrule
\end{tabular}

\subsection{Schritte: Material-Kammer einrichten}
\begin{enumerate}
  \item Materialgruppen nach Tab. 7.4 festlegen; Kartei je Gruppe nach Vorlage A.4 anlegen.
  \item Bestand zählen; Abweichung von Mindestbestand in Nachschub-Spalte eintragen.
  \item Lagerorte nummerieren und an den Regalen anschreiben; Karten mit Lagerort-Nr. verlinken.
  \item Erst rein, erst raus: Neue Ware hinter alte Ware; die älteste immer vorne.
  \item Turnus festlegen: Zählung monatlich, Prüfung wöchentlich (organisch).
  \item Stand-Kasten an der Tür: Datum letzte Prüfung, Verantwortlicher, nächste Prüfung.
\end{enumerate}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-7-1}
\caption{Abb. 7.1 -- Material-Kammer: Kartei, Regal-Nummern, Erst rein -- erst raus}
\end{figure}

\begin{baustein}
\textbf{Merksätze.}\\
Was nicht auf der Karte steht, existiert nicht.\\
Erst rein, erst raus: Der Vorrat altert von vorne.\\
Mindestbestand ist eine Bestellung, kein Wunsch.
\end{baustein}
\end{konzept}

\section{Kapitel-Checkliste: Die Material-Kammer}
\begin{checkliste}
  \item ☐ Jede Materialgruppe hat eine Bestandskarte (Vorlage A.4).
  \item ☐ Mindestbestände nach Tab. 7.4 gesetzt und geprüft.
  \item ☐ Knochenleim nur im Wasserbad geschmolzen, nie gekocht.
  \item ☐ Öllappen flach oder im Wasser gelagert, nie geknüllt.
  \item ☐ Riemen vor Belastung auf Querrisse geprüft.
  \item ☐ Erst rein, erst raus an allen Regalen sichtbar.
  \item ☐ Bestandszählung monatlich, organische Prüfung wöchentlich.
\end{checkliste}
