\chapter{Die Werkzeug-Kiste: Auswahl, Tragen und die Werkstatt im Feld}

\begin{konzept}{8.1}{Grundauswahl}
\textbf{Definition:} Die Grundauswahl ist die Liste der Werkzeuge, die 90 \% der Feld-Handwerksaufgaben abdeckt (Faustwert), ohne Spezialwerkzeug für Einzelprojekte -- sie ist ein Minimum, kein Wunschzettel.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Abdeckung: Jedes Werkzeug erfüllt mindestens zwei Aufgaben (Hammer: schlagen, zieht Nägel; Beitel: stemmt, schabt, öffnet).
  \item Ersatz: Für jedes Werkzeug ist ein Abstrakt-Ersatz dokumentiert (Tab. 8.1).
  \item Gewicht: Gesamtgewicht der Feldkiste unter 12 kg (Faustwert; darüber sinkt die Bereitschaft, sie mitzunehmen).
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Nutzungsquote: Jedes Werkzeug wurde in den letzten 3 Monaten benutzt; sonst aus der Kiste nehmen.
  \item Doppelfunktion: Anzahl der Werkzeuge mit zwei dokumentierten Einsätzen über 80 \%.
  \item Transportproben: Kiste 1 km tragen, ohne Schmerzen an Händen oder Schultern.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Spezialwerkzeug (Gewindebohrer, Zangen für Feinmechanik) gehört nicht in die Feldkiste, sondern in die Werkstatt. Wer im Feld Spezialarbeit plant, plant sie als Werkstatt-Arbeit und transportiert das Werkstück, nicht die Werkstatt.

\subsection{Tabelle: Feldkiste -- Kernbestand (Tab. 8.1)}
\begin{tabular}{p{4.0cm}p{2.4cm}p{4.6cm}}
\toprule
Werkzeug & Gewicht & Ersatz \\
\midrule
Kombizange, isolierte Griffe & 0,3 kg & Zwei Steine als Backen \\
Universalhammer 0,8 kg & 0,8 kg & Findling mit Griffkante \\
Feldmesser, feststehend & 0,2 kg & geschmiedetes Messer (Konzept 2.4) \\
Klappsäge oder Bogensäge & 0,6 kg & Sägeblatt-Ersatz, Schnur-Vielzahn \\
Stechbeitel-Set, 3 Breiten & 0,4 kg & geschliffene Nägel (Konzept 2.4) \\
Wetzstein, doppelseitig & 0,2 kg & Flusskiesel, fein \\
Feile, halbrund & 0,3 kg & grober Stein, langsamer \\
Bolle Draht 2 mm, 5 m & 0,2 kg & gesplissene Seilstränge \\
Schnur, Hanf 6 mm, 20 m & 0,3 kg & Lederriemen (Konzept 7.3) \\
Zündmittel, Streichhölzer, Feuerstahl & 0,1 kg & -- \\
\bottomrule
\end{tabular}

\subsection{Schritte: Kiste zusammenstellen}
\begin{enumerate}
  \item Starte mit Tab. 8.1; streiche jedes Werkzeug, das du nicht benennen kannst.
  \item Wiege die Kiste; über 12 kg: Doppeltes streichen oder Second-Kiste für Transport.
  \item Jedes Werkzeug mit Nummer der Inventarliste (Vorlage A.1) versehen.
  \item Ersatzspalte ausfüllen (Werkstatt-Wissen aus den Kapiteln 2 bis 7).
  \item Nutzungsprotokoll 3 Monate führen; ungenutztes Werkzeug herausnehmen.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Zwei Aufgaben pro Werkzeug, sonst bleibt es zu Hause.\\
Was du nicht benennen kannst, benutzt du nicht.\\
Zwölf Kilo sind die Grenze zwischen Kiste und Last.
\end{baustein}
\end{konzept}

\begin{konzept}{8.2}{Tragen und Schützen}
\textbf{Definition:} Tragen heißt, Werkzeug so zu verstauen, dass Klingen gesichert, Griffe geschont und jedes Werkzeug in unter 10 Sekunden entnehmbar ist; Schützen heißt, Werkzeug gegen Wasser, Sturz und Zugriff zu sichern.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Klingensicherung: Jede scharfe Klinge in Scheide oder Umschlag; Prüfung durch Schütteltest -- kein Klingengeräusch.
  \item Griffschutz: Kanten und Platten nicht auf Hammerstiele liegen; Stiel auf Stiel bricht Stiel.
  \item Wetter: Kistendichtung gegen Regen (Wachs am Deckel), Tragegriff für zwei Hände.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Entnahme-Zeit: Jedes Werkzeug in unter 10 Sekunden erreichbar (Zeitprobe bei Dunkelheit).
  \item Zustandsquote: Nach jedem Transport ist jedes Werkzeug unbeschädigt.
  \item Zugriffsregel: Kiste nie offen liegen lassen; nach jeder Nutzung kontrollieren.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Der beste Kistenschutz ist die Nutzungsdauer eines Menschen: Ein Werkstatt-Kistengehilfe (Konzept 9.1) trägt, passt auf und lernt dabei -- die Kiste allein transportiert nicht.

\subsection{Tabelle: Tragesystem Stadt/Land (Tab. 8.2)}
\begin{tabular}{p{3.4cm}p{4.4cm}p{4.2cm}}
\toprule
Kriterium & Stadt & Land \\
\midrule
Behälter & Werkzeugkasten mit Schloss, Feststoffdeckel & Rucksack mit Lederboden, Regenhülle \\
Transportweg & Treppe, Aufzug, Straßenweg, alles befestigt & Feldweg, Weg bis zur Baustelle oft 1 km \\
Diebstahlschutz & Schloss, keine Wertraum-Anzeige & Hofregel, Kiste nie unbeaufsichtigt am Weg \\
Wetter & Regenhülle, Feuchtigkeit im Keller prüfen & Regenhülle, Nacht im Haus, nicht im Feld \\
\bottomrule
\end{tabular}

\subsection{Schritte: Kiste packen}
\begin{enumerate}
  \item Boden: schwere, flache Teile (Steine, Amboss-Stück), jede Kante nach oben gefettet.
  \item Mittelschicht: Werkzeuge in Scheiden, Griffe alle in eine Richtung.
  \item Oberschicht: Kleinteile, Schnur, Zündmittel in Beutel mit Rollverschluss oder Knoten.
  \item Schütteltest: Kiste schütteln; Klappergeräusch = nachpolstern mit Lappen (Konzept 7.3).
  \item Feucht-Prüfer (Kreide im Beutel) einlegen: Kreide weich = zu feucht.
  \item Inventarzettel in Deckelinnenseite kleben; Zähle nach jedem Schließen.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Kein Klingengeräusch im Schütteltest.\\
Griff auf Griff bricht Griff.\\
Weiche Kreide ist ein Feuchtemesser.
\end{baustein}
\end{konzept}

\begin{konzept}{8.3}{Feldwerkstatt aufbauen}
\textbf{Definition:} Die Feldwerkstatt ist die Arbeitsumgebung am Einsatzort: Unterlage, Werkzeugkreuz, Materialstapel und Sitzgelegenheit in 4 m Radius -- in unter 60 Minuten aufgebaut, in unter 20 Minuten abgebaut.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Untergrund: trocken, eben, 2 m × 2 m; bei Nässe Bretter als Boden (Konzept 3.4).
  \item Werkzeugkreuz: Kiste am Platz des Rechts- beziehungsweise Linkshänders, Material links, Werkstück Mitte, Abfall rechts.
  \item Sicherheit: Erste-Hilfe-Set der Reihe (Band 8) in Reichweite, Notwasser, Klingensicherung am Gürtel.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Aufbauzeit: Unter 60 Minuten (Zeitstopp, Protokoll Vorlage A.5).
  \item Wegequote: Für keinen Arbeitsschritt mehr als zwei Schritte vom Platz.
  \item Abbau-Rückstand: Kein Werkzeug am Platz zurückgeblieben; Zählliste bestätigt.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Die Feldwerkstatt ist keine Schmiede: Ohne transportierten Amboss und Feuerrecht (örtlich prüfen) bleiben Schmiedearbeiten in der Werkstatt (Kapitel 2).

\subsection{Tabelle: Feldwerkstatt-Checkliste Arbeitsplätze (Tab. 8.3)}
\begin{tabular}{p{3.4cm}p{4.0cm}p{4.0cm}}
\toprule
Element & Stadt & Land \\
\midrule
Unterlage & Bretter, Plane auf Beton & Plane auf gemähtem Gras \\
Werkbank & Zwei Böcke, Tür auf Sägeböcken & Zwei Stümpfe, Bohle oben \\
Sitz & Kübel, Treppenstufe & Stumpf, gefällter Ast \\
Lager Werkstoff & senkrechte Stapel an Wand & Stapel windabgewandt \\
Abfall & Sack mitnehmen & Gruben-Entsorgung 20 m Abstand \\
\bottomrule
\end{tabular}

\subsection{Schritte: Aufbau in 60 Minuten}
\begin{enumerate}
  \item Gelände prüfen (Tab. 8.3), 2 m × 2 m freilegen, Unterlage auslegen.
  \item Werkbank aufbauen: zwei Böcke/Stümpfe, Bohle oder Tür auflegen, Wackeltest mit 20 kg.
  \item Kiste an die Greifseite, Materialstapel links, Abfall rechts platzieren.
  \item Sitz aufstellen, Erste-Hilfe-Set und Notwasser in 2 m platzieren.
  \item Zeitstopp beenden; Aufbauzeit in Vorlage A.5 notieren.
  \item Arbeiten nach den Kapiteln 3 bis 7; Klingensicherung nach jedem Schritt.
  \item Abbau: Zählliste, Werkzeugkreuz räumen, Unterlage schütteln, Abfall mitnehmen; Abbauzeit notieren.
\end{enumerate}

\begin{figure}[htbp]
\centering
\includesvg[width=\textwidth]{illustrationen/abb-8-1}
\caption{Abb. 8.1 -- Feldwerkstatt: Werkzeugkreuz, Werkbank, Material- und Abfallplatz}
\end{figure}

\begin{baustein}
\textbf{Merksätze.}\\
Zwei Schritte, ein Griff: Wer mehr läuft, hat falsch gebaut.\\
Werkzeugkreuz vor Arbeit, Zählliste nach Arbeit.\\
Die Feldwerkstatt ist eine Werkstatt ohne Feuer -- Schmiede bleibt zu Hause.
\end{baustein}
\end{konzept}

\section{Kapitel-Checkliste: Die Werkzeug-Kiste}
\begin{checkliste}
  \item ☐ Kiste unter 12 kg, jedes Werkzeug mit Nummer und Doppelaufgabe.
  \item ☐ Nutzungsprotokoll geführt; ungenutztes Werkzeug herausgenommen.
  \item ☐ Schütteltest bestanden: kein Geräusch, keine losen Klingen.
  \item ☐ Feucht-Prüfer (Kreide) in der Kiste, regelmäßig geprüft.
  \item ☐ Feldwerkstatt-Aufbau unter 60 Minuten, Abbau unter 20 Minuten.
  \item ☐ Erste-Hilfe-Set (Band 8) und Notwasser in 2 m am Arbeitsplatz.
  \item ☐ Zählliste nach jedem Abbau bestätigt.
\end{checkliste}

\chapter{Die Weitergabe: die Hand lehrt die Hand}

\begin{konzept}{9.1}{Vier Stufen der Weitergabe}
\textbf{Definition:} Die Vier-Stufen-Methode ist die Weitergabe einer Fertigkeit in festgelegter Reihenfolge: (1) vorzeigen mit Benennen, (2) mitmachen lassen unter Anleitung, (3) zuschauen und Fehler benennen lassen, (4) Lernende lehrt eine dritte Person, während der Lehrer bewertet.

\textbf{Dreifache Prüfung:}
\begin{enumerate}
  \item Fertigkeit: Der Lehrer beherrscht die Arbeit zweimal fehlerfrei nacheinander (Konzept 1.1 Bewertung 3).
  \item Material: Es steht Übungsmaterial für den dreifachen Verbrauch bereit (nicht das letzte Stück).
  \item Sicherheit: Der Lernende kennt die Warnungen der Kapitel 2, 3 und 4, bevor Stufe 1 beginnt.
\end{enumerate}

\textbf{Dreifache Bewertung:}
\begin{enumerate}
  \item Stufe 2: Lernender führt die Arbeit unter Anleitung fehlerfrei aus.
  \item Stufe 3: Lernender benennt drei echte Fehler am Dritten (nicht erfundene).
  \item Stufe 4: Der neue Lehrer vermittelt die Fertigkeit in eigener Sprache, ohne Vorlage zu wiederholen.
\end{enumerate}

\textbf{Ehrliche Grenzen:} Fertigkeiten unter Risiko (Fällen, Schmieden, Härtung) weiterzugeben dauert Monate, nicht Stunden. Wer eine Stufe überspringt, gibt nicht Fertigkeit weiter, sondern Risiko.

\subsection{Tabelle: Weitergabe-Planung Stadt/Land (Tab. 9.1)}
\begin{tabular}{p{3.4cm}p{4.4cm}p{4.2cm}}
\toprule
Kriterium & Stadt & Land \\
\midrule
Lerngruppe & 2 bis 3 Personen aus Nachbarschaft & 1 bis 2 Personen vom Hof oder Dorf \\
Ort & Gemeinschaftswerkstatt, Innenhof & Scheune, Feldrand \\
Material & Übungsrestholz aus Altbauteilen & Windwurf, Reste der Ernte-Aufarbeitung \\
Zeitfenster & Wochenenden, Nutzungsfenster (Konzept 6.1) & Winter, Schlechtwetterzeit \\
Nachweis & Protokoll Vorlage A.6 & Protokoll Vorlage A.6, Dorfkopie \\
\bottomrule
\end{tabular}

\subsection{Schritte: Stufe 1 und 2 durchführen}
\begin{enumerate}
  \item Arbeitsplatz nach Konzept 8.3 aufbauen; Lernender zuschauen mit Ruhe (keine Fragen während der Vorführung).
  \item Vorführen in normaler Geschwindigkeit; jeden Schritt mit Werkzeug-Namen und Ziel benennen.
  \item Vorführen in Zeitlupe; Lernender darf nur nach Ende Fragen stellen, notieren in Vorlage A.6.
  \item Stufe 2: Lernender führt aus, Lehrer steht halbe Armlänge daneben; Korrektur nur durch Wort, nie durch Wegnehmen des Werkzeugs.
  \item Fehler sofort benennen, Korrektur vor dem nächsten Schlag oder Schnitt.
  \item Nach dreimal fehlerfreier Ausführung: Stufe 2 bestanden; Protokoll abzeichnen.
\end{enumerate}

\subsection{Schritte: Stufe 3 und 4 durchführen}
\begin{enumerate}
  \item Dritte Person (Anfänger) heranholen; Lernender demonstriert, wie gelehrt.
  \item Lehrer beobachtet nur; notiert drei Fehler des Lernenden in Vorlage A.6.
  \item Nachbesprechung: Lernender benennt eigene Fehler, Lehrer ergänzt Verpasstes.
  \item Stufe 4 erst nach mindestens 10 selbstständigen Ausführungen: Lernender lehrt die nächste Person.
  \item Beide Protokolle (lehr-end und lern-end) in die Werkstatt-Akte (Vorlage A.6) heften.
\end{enumerate}

\begin{baustein}
\textbf{Merksätze.}\\
Wer nicht zweimal kann, darf nicht lehren.\\
Wort statt Griff: das Werkzeug aus der Hand nehmen ist eine Korrektur der Würde.\\
Erst üben am Restholz, dann arbeiten am Stück.
\end{baustein}
\end{konzept}

\section{Kapitel-Checkliste: Die Weitergabe}
\begin{checkliste}
  \item ☐ Lehrer hat die Fertigkeit zweimal fehlerfrei gezeigt (Konzept 1.1).
  \item ☐ Übungsmaterial im dreifachen Verbrauch vorhanden.
  \item ☐ Warnungen der Kapitel 2, 3 und 4 vor Stufe 1 vermittelt.
  \item ☐ Stufen in Ordnung 1 bis 4, keine übersprungen.
  \item ☐ Korrektur nur durch Wort; Werkzeug nie weggenommen.
  \item ☐ Stufe 3 erst nach 10 selbstständigen Ausführungen.
  \item ☐ Protokolle in Vorlage A.6 geführt und abgezeichnet.
\end{checkliste}
TEXEOF
echo done"}

